import type { PracticeExercise, PracticeTopic } from './catalog';

type Code = Pick<PracticeExercise,'starter'|'solution'>;
const error = '#[derive(Debug)]\npub enum InputError { InvalidInput }\n';
function code(py:string,js:string,rs:string,bodies:[string,string,string],structs=''):Code {
  const python=(body:string)=>`import math\n\n${py}:\n    finite = lambda x: type(x) in (int,float) and math.isfinite(x)\n${body.split('\n').map(s=>'    '+s).join('\n')}\n`;
  const javascript=(body:string)=>`${js} {\n${body.split('\n').map(s=>'  '+s).join('\n')}\n}\n`;
  const rust=(body:string)=>`${error}${structs}${rs} {\n${body.split('\n').map(s=>'    '+s).join('\n')}\n}\n`;
  return {starter:{python:python('raise NotImplementedError("Реализуйте правило")'),javascript:javascript('throw new Error("Реализуйте правило");'),rust:rust('todo!("Реализуйте правило")')},solution:{python:python(bodies[0]),javascript:javascript(bodies[1]),rust:rust(bodies[2])}};
}
type Row=[string,string,string,string,Record<string,unknown>,unknown,string,string[],number,Code?];
function topic(id:string,title:string,prerequisites:string[],formula:string,contract:string,snippets:Code,rows:[Row,Row,Row]):PracticeTopic{
  const topicId='concept.'+id;
  return{id:topicId,lessonId:'math',title,sourceSection:`src/concepts.ts · ${id}`,prerequisites:prerequisites.map(id=>'concept.'+id),exercises:rows.map((r,i)=>({id:topicId+'.'+['guided','transfer-a','transfer-b'][i],topicId,title:r[0],mode:i?'transfer':'guided',prompt:r[1]+' '+contract,formula,hints:[r[2]],explanation:r[3],...(r[9]||snippets),fixtures:[{input:JSON.stringify(r[4]),output:JSON.stringify(r[5])}],quiz:{question:r[6],options:r[7],correctIndex:r[8],explanation:r[3]}}))};
}
const scalarContract='Числа конечны и лежат в пределах ±100. Неверные значения отклоняются как ValueError/RangeError/InputError. Python bool не считается числом. Сравнение atol=1e−12,rtol=1e−10; конечные разности проверяются отдельно с atol=1e−7,rtol=1e−6.';
const vectorContract='Векторы непустые, нужные длины совпадают, максимум 64 элемента. Числа конечны в ±10000; вход не менять. Неверные значения отклоняются: ValueError/RangeError/InputError. atol=1e−12,rtol=1e−10.';
const probabilityContract='Вероятности — непустой вектор длины 1…64, конечные p≥0, сумма 1 в пределах 1e−10. Пустые, отрицательные, неконечные и ненормированные p отклоняются. Логарифм натуральный. atol=1e−12,rtol=1e−10.';

