const softmax=code('def softmax(z: list[float], temperature: float) -> list[float]','function softmax(z, temperature)','pub fn softmax(z: &[f64], temperature: f64) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(z)<=64 or any(not finite(a) or abs(a)>10000 for a in z) or not finite(temperature) or not .1<=temperature<=10: raise ValueError("Неверные логиты или температура")\nm=max(z);e=[math.exp((a-m)/temperature) for a in z];total=sum(e)\nreturn [a/total for a in e]',
  'if(!Array.isArray(z)||!z.length||z.length>64||z.some(a=>!Number.isFinite(a)||Math.abs(a)>10000)||!Number.isFinite(temperature)||temperature<.1||temperature>10)throw new RangeError("Неверные логиты или температура");const m=Math.max(...z),e=z.map(a=>Math.exp((a-m)/temperature)),total=e.reduce((s,a)=>s+a,0);return e.map(a=>a/total);',
  'if z.is_empty()||z.len()>64||z.iter().any(|a|!a.is_finite()||a.abs()>10000.0)||!temperature.is_finite()||!(0.1..=10.0).contains(&temperature){return Err(InputError::InvalidInput);}\nlet m=z.iter().copied().fold(f64::NEG_INFINITY,f64::max);let e:Vec<f64>=z.iter().map(|a|((a-m)/temperature).exp()).collect();let total:f64=e.iter().sum();Ok(e.iter().map(|a|a/total).collect())',
]);

const layerNorm=code('def layer_norm(x: list[float], gamma: list[float], beta: list[float], eps: float) -> list[float]','function layerNorm(x, gamma, beta, eps)','pub fn layer_norm(x: &[f64], gamma: &[f64], beta: &[f64], eps: f64) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(x)<=64 or len(x)!=len(gamma) or len(x)!=len(beta) or any(not finite(v) or abs(v)>1000 for v in x+gamma+beta) or not finite(eps) or not 1e-12<=eps<=1: raise ValueError("Неверные параметры нормализации")\nmean=sum(x)/len(x);variance=sum((v-mean)**2 for v in x)/len(x)\nreturn [g*(v-mean)/math.sqrt(variance+eps)+b for v,g,b in zip(x,gamma,beta)]',
  'if(!Array.isArray(x)||!Array.isArray(gamma)||!Array.isArray(beta)||!x.length||x.length>64||x.length!==gamma.length||x.length!==beta.length||[...x,...gamma,...beta].some(v=>!Number.isFinite(v)||Math.abs(v)>1000)||!Number.isFinite(eps)||eps<1e-12||eps>1)throw new RangeError("Неверные параметры нормализации");const mean=x.reduce((s,v)=>s+v,0)/x.length,variance=x.reduce((s,v)=>s+(v-mean)**2,0)/x.length;return x.map((v,i)=>gamma[i]*(v-mean)/Math.sqrt(variance+eps)+beta[i]);',
  'if x.is_empty()||x.len()>64||x.len()!=gamma.len()||x.len()!=beta.len()||x.iter().chain(gamma).chain(beta).any(|v|!v.is_finite()||v.abs()>1000.0)||!eps.is_finite()||!(1e-12..=1.0).contains(&eps){return Err(InputError::InvalidInput);}\nlet mean=x.iter().sum::<f64>()/x.len() as f64;let variance=x.iter().map(|v|(v-mean).powi(2)).sum::<f64>()/x.len() as f64;Ok(x.iter().zip(gamma).zip(beta).map(|((v,g),b)|g*(v-mean)/(variance+eps).sqrt()+b).collect())',
]);
const mse=code('def mean_squared_error(predictions: list[float], targets: list[float]) -> float','function meanSquaredError(predictions, targets)','pub fn mean_squared_error(predictions: &[f64], targets: &[f64]) -> Result<f64, InputError>',[
  'if not 1<=len(predictions)<=64 or len(predictions)!=len(targets) or any(not finite(v) or abs(v)>1000 for v in predictions+targets): raise ValueError("Несовместимые предсказания и цели")\nreturn sum((p-y)**2 for p,y in zip(predictions,targets))/len(predictions)',
  'if(!Array.isArray(predictions)||!Array.isArray(targets)||!predictions.length||predictions.length>64||predictions.length!==targets.length||[...predictions,...targets].some(v=>!Number.isFinite(v)||Math.abs(v)>1000))throw new RangeError("Несовместимые предсказания и цели");return predictions.reduce((s,p,i)=>s+(p-targets[i])**2,0)/predictions.length;',
  'if predictions.is_empty()||predictions.len()>64||predictions.len()!=targets.len()||predictions.iter().chain(targets).any(|v|!v.is_finite()||v.abs()>1000.0){return Err(InputError::InvalidInput);}\nOk(predictions.iter().zip(targets).map(|(p,y)|(p-y).powi(2)).sum::<f64>()/predictions.len() as f64)',
]);
const crossEntropy=code('def logit_cross_entropy(z: list[float], target: int) -> float','function logitCrossEntropy(z, target)','pub fn logit_cross_entropy(z: &[f64], target: usize) -> Result<f64, InputError>',[
  'if not 2<=len(z)<=64 or any(not finite(v) or abs(v)>10000 for v in z) or type(target) is not int or not 0<=target<len(z): raise ValueError("Неверные логиты или индекс класса")\nm=max(z)\nreturn math.log(sum(math.exp(v-m) for v in z))+(m-z[target])',
  'if(!Array.isArray(z)||z.length<2||z.length>64||z.some(v=>!Number.isFinite(v)||Math.abs(v)>10000)||!Number.isInteger(target)||target<0||target>=z.length)throw new RangeError("Неверные логиты или индекс класса");const m=Math.max(...z);return Math.log(z.reduce((s,v)=>s+Math.exp(v-m),0))+(m-z[target]);',
  'if z.len()<2||z.len()>64||z.iter().any(|v|!v.is_finite()||v.abs()>10000.0)||target>=z.len(){return Err(InputError::InvalidInput);}\nlet m=z.iter().copied().fold(f64::NEG_INFINITY,f64::max);Ok(z.iter().map(|v|(v-m).exp()).sum::<f64>().ln()+(m-z[target]))',
]);
const learningRate=code('def sgd_step(theta: float, gradient: float, eta: float) -> float','function sgdStep(theta, gradient, eta)','pub fn sgd_step(theta: f64, gradient: f64, eta: f64) -> Result<f64, InputError>',[
  'if any(not finite(v) or abs(v)>100 for v in (theta,gradient)) or not finite(eta) or not 0<=eta<=3: raise ValueError("Неверные параметры шага")\nreturn theta-eta*gradient',
  'if([theta,gradient].some(v=>!Number.isFinite(v)||Math.abs(v)>100)||!Number.isFinite(eta)||eta<0||eta>3)throw new RangeError("Неверные параметры шага");return theta-eta*gradient;',
  'if [theta,gradient].iter().any(|v|!v.is_finite()||v.abs()>100.0)||!eta.is_finite()||!(0.0..=3.0).contains(&eta){return Err(InputError::InvalidInput);}\nOk(theta-eta*gradient)',
]);
const sharedGraph=code('def backprop_graph(x: float, w: float, target: float) -> list[float]','function backpropGraph(x, w, target)','pub fn backprop_graph(x: f64, w: f64, target: f64) -> Result<Vec<f64>, InputError>',[
  'if any(not finite(v) or abs(v)>4 for v in (x,w,target)): raise ValueError("Неверные параметры графа")\nq=w*x;p=q*q+q;error=p-target\ndq=error*(2*q+1)\nreturn [q,p,error*error/2,dq*w,dq*x]',
  'if([x,w,target].some(v=>!Number.isFinite(v)||Math.abs(v)>4))throw new RangeError("Неверные параметры графа");const q=w*x,p=q*q+q,error=p-target,dq=error*(2*q+1);return [q,p,error*error/2,dq*w,dq*x];',
  'if [x,w,target].iter().any(|v|!v.is_finite()||v.abs()>4.0){return Err(InputError::InvalidInput);}\nlet q=w*x;let p=q*q+q;let error=p-target;let dq=error*(2.0*q+1.0);Ok(vec![q,p,error*error/2.0,dq*w,dq*x])',
]);
const fit=code('def fit_standardizer(train: list[float]) -> list[float]','function fitStandardizer(train)','pub fn fit_standardizer(train: &[f64]) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(train)<=64 or any(not finite(v) or abs(v)>1000 for v in train): raise ValueError("Неверная обучающая выборка")\nmean=sum(train)/len(train);variance=sum((v-mean)**2 for v in train)/len(train)\nreturn [mean,math.sqrt(variance) if variance>0 else 1]',
  'if(!Array.isArray(train)||!train.length||train.length>64||train.some(v=>!Number.isFinite(v)||Math.abs(v)>1000))throw new RangeError("Неверная обучающая выборка");const mean=train.reduce((s,v)=>s+v,0)/train.length,variance=train.reduce((s,v)=>s+(v-mean)**2,0)/train.length;return [mean,variance>0?Math.sqrt(variance):1];',
  'if train.is_empty()||train.len()>64||train.iter().any(|v|!v.is_finite()||v.abs()>1000.0){return Err(InputError::InvalidInput);}\nlet mean=train.iter().sum::<f64>()/train.len() as f64;let variance=train.iter().map(|v|(v-mean).powi(2)).sum::<f64>()/train.len() as f64;Ok(vec![mean,if variance>0.0{variance.sqrt()}else{1.0}])',
]);
const transform=code('def transform_scalar(x: float, mean: float, scale: float) -> float','function transformScalar(x, mean, scale)','pub fn transform_scalar(x: f64, mean: f64, scale: f64) -> Result<f64, InputError>',[
  'if any(not finite(v) or abs(v)>1000 for v in (x,mean)) or not finite(scale) or not 1e-12<=scale<=2000: raise ValueError("Неверные параметры преобразования")\nreturn (x-mean)/scale',
  'if([x,mean].some(v=>!Number.isFinite(v)||Math.abs(v)>1000)||!Number.isFinite(scale)||scale<1e-12||scale>2000)throw new RangeError("Неверные параметры преобразования");return (x-mean)/scale;',
  'if [x,mean].iter().any(|v|!v.is_finite()||v.abs()>1000.0)||!scale.is_finite()||!(1e-12..=2000.0).contains(&scale){return Err(InputError::InvalidInput);}\nOk((x-mean)/scale)',
]);

const gap=code('def generalization_gap(train_losses: list[float], heldout_losses: list[float]) -> list[float]','function generalizationGap(train_losses, heldout_losses)','pub fn generalization_gap(train_losses: &[f64], heldout_losses: &[f64]) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(train_losses)<=64 or not 1<=len(heldout_losses)<=64 or any(not finite(v) or not 0<=v<=10000 for v in train_losses+heldout_losses): raise ValueError("Неверные списки потерь")\na=sum(train_losses)/len(train_losses);b=sum(heldout_losses)/len(heldout_losses)\nreturn [a,b,b-a]',
  'if(!Array.isArray(train_losses)||!Array.isArray(heldout_losses)||!train_losses.length||!heldout_losses.length||train_losses.length>64||heldout_losses.length>64||[...train_losses,...heldout_losses].some(v=>!Number.isFinite(v)||v<0||v>10000))throw new RangeError("Неверные списки потерь");const a=train_losses.reduce((s,v)=>s+v,0)/train_losses.length,b=heldout_losses.reduce((s,v)=>s+v,0)/heldout_losses.length;return [a,b,b-a];',
  'if train_losses.is_empty()||heldout_losses.is_empty()||train_losses.len()>64||heldout_losses.len()>64||train_losses.iter().chain(heldout_losses).any(|v|!v.is_finite()||!(0.0..=10000.0).contains(v)){return Err(InputError::InvalidInput);}\nlet a=train_losses.iter().sum::<f64>()/train_losses.len() as f64;let b=heldout_losses.iter().sum::<f64>()/heldout_losses.len() as f64;Ok(vec![a,b,b-a])',
]);
const l2=code('def l2_penalty_and_grad(weights: list[float], strength: float) -> list[float]','function l2PenaltyAndGrad(weights, strength)','pub fn l2_penalty_and_grad(weights: &[f64], strength: f64) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(weights)<=64 or any(not finite(v) or abs(v)>100 for v in weights) or not finite(strength) or not 0<=strength<=1: raise ValueError("Неверные параметры штрафа")\nreturn [strength*sum(v*v for v in weights)/2]+[strength*v for v in weights]',
  'if(!Array.isArray(weights)||!weights.length||weights.length>64||weights.some(v=>!Number.isFinite(v)||Math.abs(v)>100)||!Number.isFinite(strength)||strength<0||strength>1)throw new RangeError("Неверные параметры штрафа");return [strength*weights.reduce((s,v)=>s+v*v,0)/2,...weights.map(v=>strength*v)];',
  'if weights.is_empty()||weights.len()>64||weights.iter().any(|v|!v.is_finite()||v.abs()>100.0)||!strength.is_finite()||!(0.0..=1.0).contains(&strength){return Err(InputError::InvalidInput);}\nlet mut out=vec![strength*weights.iter().map(|v|v*v).sum::<f64>()/2.0];out.extend(weights.iter().map(|v|strength*v));Ok(out)',
]);
const init=code('def fan_in_scale(fan_in: int, fan_out: int, kind: str) -> list[float]','function fanInScale(fan_in, fan_out, kind)','pub fn fan_in_scale(fan_in: usize, fan_out: usize, kind: &str) -> Result<Vec<f64>, InputError>',[
  'if type(fan_in) is not int or type(fan_out) is not int or not 1<=fan_in<=1000000 or not 1<=fan_out<=1000000 or kind not in ("he","xavier"): raise ValueError("Неверные параметры инициализации")\nvariance=2/fan_in if kind=="he" else 2/(fan_in+fan_out)\nreturn [variance,math.sqrt(variance)]',
  'if(!Number.isInteger(fan_in)||!Number.isInteger(fan_out)||fan_in<1||fan_out<1||fan_in>1000000||fan_out>1000000||!["he","xavier"].includes(kind))throw new RangeError("Неверные параметры инициализации");const variance=kind==="he"?2/fan_in:2/(fan_in+fan_out);return [variance,Math.sqrt(variance)];',
  'if fan_in==0||fan_out==0||fan_in>1000000||fan_out>1000000{return Err(InputError::InvalidInput);}\nlet variance=match kind{"he"=>2.0/fan_in as f64,"xavier"=>2.0/(fan_in+fan_out) as f64,_=>return Err(InputError::InvalidInput)};Ok(vec![variance,variance.sqrt()])',
]);
const batches=code('def batch_indices(n: int, batch_size: int) -> list[list[float]]','function batchIndices(n, batch_size)','pub fn batch_indices(n: usize, batch_size: usize) -> Result<Vec<Vec<f64>>, InputError>',[
  'if type(n) is not int or type(batch_size) is not int or not 1<=n<=10000 or not 1<=batch_size<=10000: raise ValueError("Неверные размеры пакетов")\nreturn [list(range(start,min(start+batch_size,n))) for start in range(0,n,batch_size)]',
  'if(!Number.isInteger(n)||!Number.isInteger(batch_size)||n<1||n>10000||batch_size<1||batch_size>10000)throw new RangeError("Неверные размеры пакетов");const out=[];for(let start=0;start<n;start+=batch_size){const row=[];for(let i=start;i<Math.min(start+batch_size,n);i++)row.push(i);out.push(row);}return out;',
  'if n==0||n>10000||batch_size==0||batch_size>10000{return Err(InputError::InvalidInput);}\nOk((0..n).step_by(batch_size).map(|start|(start..(start+batch_size).min(n)).map(|i|i as f64).collect()).collect())',
]);
const epochLoss=code('def weighted_epoch_loss(means: list[float], counts: list[int]) -> float','function weightedEpochLoss(means, counts)','pub fn weighted_epoch_loss(means: &[f64], counts: &[usize]) -> Result<f64, InputError>',[
  'if not 1<=len(means)<=64 or len(means)!=len(counts) or any(not finite(v) or not 0<=v<=10000 for v in means) or any(type(n) is not int or not 1<=n<=10000 for n in counts): raise ValueError("Неверные средние или размеры пакетов")\nreturn sum(m*n for m,n in zip(means,counts))/sum(counts)',
  'if(!Array.isArray(means)||!Array.isArray(counts)||!means.length||means.length>64||means.length!==counts.length||means.some(v=>!Number.isFinite(v)||v<0||v>10000)||counts.some(n=>!Number.isInteger(n)||n<1||n>10000))throw new RangeError("Неверные средние или размеры пакетов");return means.reduce((s,m,i)=>s+m*counts[i],0)/counts.reduce((s,n)=>s+n,0);',
  'if means.is_empty()||means.len()>64||means.len()!=counts.len()||means.iter().any(|v|!v.is_finite()||!(0.0..=10000.0).contains(v))||counts.iter().any(|n|*n==0||*n>10000){return Err(InputError::InvalidInput);}\nOk(means.iter().zip(counts).map(|(m,n)|m*(*n as f64)).sum::<f64>()/counts.iter().sum::<usize>() as f64)',
]);
const decay=code('def adamw_decay_step(theta: list[float], adaptive: list[float], eta: float, strength: float) -> list[float]','function adamwDecayStep(theta, adaptive, eta, strength)','pub fn adamw_decay_step(theta: &[f64], adaptive: &[f64], eta: f64, strength: f64) -> Result<Vec<f64>, InputError>',[
  'if not 1<=len(theta)<=64 or len(theta)!=len(adaptive) or any(not finite(v) or abs(v)>100 for v in theta+adaptive) or any(not finite(v) or not 0<=v<=1 for v in (eta,strength)): raise ValueError("Неверные параметры AdamW")\nreturn [w*(1-eta*strength)-eta*u for w,u in zip(theta,adaptive)]',
  'if(!Array.isArray(theta)||!Array.isArray(adaptive)||!theta.length||theta.length>64||theta.length!==adaptive.length||[...theta,...adaptive].some(v=>!Number.isFinite(v)||Math.abs(v)>100)||[eta,strength].some(v=>!Number.isFinite(v)||v<0||v>1))throw new RangeError("Неверные параметры AdamW");return theta.map((w,i)=>w*(1-eta*strength)-eta*adaptive[i]);',
  'if theta.is_empty()||theta.len()>64||theta.len()!=adaptive.len()||theta.iter().chain(adaptive).any(|v|!v.is_finite()||v.abs()>100.0)||[eta,strength].iter().any(|v|!v.is_finite()||!(0.0..=1.0).contains(v)){return Err(InputError::InvalidInput);}\nOk(theta.iter().zip(adaptive).map(|(w,u)|w*(1.0-eta*strength)-eta*u).collect())',
]);
const metrics=code('def classification_metrics(p: list[float], labels: list[float], threshold: float) -> dict','function classificationMetrics(p, labels, threshold)','pub fn classification_metrics(p: &[f64], labels: &[f64], threshold: f64) -> Result<Metrics, InputError>',[
  'if not 1<=len(p)<=64 or len(p)!=len(labels) or any(not finite(v) or not 0<=v<=1 for v in p) or any(not finite(y) or y not in (0,1) for y in labels) or not finite(threshold) or not 0<=threshold<=1: raise ValueError("Неверные данные метрик")\ntp=fp=fn=tn=0\nfor v,y in zip(p,labels):\n    if v>=threshold:\n        if y==1: tp+=1\n        else: fp+=1\n    else:\n        if y==1: fn+=1\n        else: tn+=1\nreturn {"accuracy":(tp+tn)/len(p),"precisionDefined":tp+fp>0,"precision":tp/(tp+fp) if tp+fp>0 else 0,"recallDefined":tp+fn>0,"recall":tp/(tp+fn) if tp+fn>0 else 0,"counts":[tp,fp,fn,tn]}',
  'if(!Array.isArray(p)||!Array.isArray(labels)||!p.length||p.length>64||p.length!==labels.length||p.some(v=>!Number.isFinite(v)||v<0||v>1)||labels.some(y=>!Number.isFinite(y)||(y!==0&&y!==1))||!Number.isFinite(threshold)||threshold<0||threshold>1)throw new RangeError("Неверные данные метрик");let tp=0,fp=0,fn=0,tn=0;p.forEach((v,i)=>{if(v>=threshold){if(labels[i]===1)tp++;else fp++;}else{if(labels[i]===1)fn++;else tn++;}});return {accuracy:(tp+tn)/p.length,precisionDefined:tp+fp>0,precision:tp+fp>0?tp/(tp+fp):0,recallDefined:tp+fn>0,recall:tp+fn>0?tp/(tp+fn):0,counts:[tp,fp,fn,tn]};',
  'if p.is_empty()||p.len()>64||p.len()!=labels.len()||p.iter().any(|v|!v.is_finite()||!(0.0..=1.0).contains(v))||labels.iter().any(|y|!y.is_finite()||(*y!=0.0&&*y!=1.0))||!threshold.is_finite()||!(0.0..=1.0).contains(&threshold){return Err(InputError::InvalidInput);}\nlet(mut tp,mut fp,mut miss,mut tn)=(0.0,0.0,0.0,0.0);for(v,y)in p.iter().zip(labels){if *v>=threshold{if *y==1.0{tp+=1.0;}else{fp+=1.0;}}else if *y==1.0{miss+=1.0;}else{tn+=1.0;}}Ok(Metrics{accuracy:(tp+tn)/p.len() as f64,precisionDefined:tp+fp>0.0,precision:if tp+fp>0.0{tp/(tp+fp)}else{0.0},recallDefined:tp+miss>0.0,recall:if tp+miss>0.0{tp/(tp+miss)}else{0.0},counts:vec![tp,fp,miss,tn]})',
], '#[allow(non_snake_case)]\npub struct Metrics { pub accuracy:f64,pub precisionDefined:bool,pub precision:f64,pub recallDefined:bool,pub recall:f64,pub counts:Vec<f64> }\n');

